def _has_code(func: Optional[Callable[..., Any]], code: CodeType) ->Optional[
    Callable[..., Any]]:
    if func is None:
        return None
    func_code = getattr(func, '__code__', None)
    if func_code is code:
        return func
    return None

def get_func(frame: FrameType) ->Optional[Callable[..., Any]]:
    code = frame.f_code
    if code.co_name is None:
        return None
    for name in ('self', 'cls'):
        if name in frame.f_locals:
            obj = frame.f_locals[name]
            func = get_func_in_mro(obj, code)
            if func is not None:
                return func
            func = get_func_in_mro(type(obj), code)
            if func is not None:
                return func
    candidate = frame.f_globals.get(code.co_name, None)
    return _has_code(candidate, code)

